{"windows":"// Place your key bindings in this file to override the defaults
[
    {
        "key": "ctrl+shift+i",
        "command": "workbench.action.chat.open",
        "when": "!chatSetupHidden"
    },
    {
        "key": "ctrl+alt+i",
        "command": "-workbench.action.chat.open",
        "when": "!chatSetupHidden"
    },
    {
        "key": "ctrl+alt+i",
        "command": "workbench.action.chat.openAgent",
        "when": "config.chat.agent.enabled && !chatSetupHidden"
    },
    {
        "key": "ctrl+shift+i",
        "command": "-workbench.action.chat.openAgent",
        "when": "config.chat.agent.enabled && !chatSetupHidden"
    },
    {
        "key": "ctrl+alt+o",
        "command": "-workbench.action.remote.showMenu"
    },
    {
        "key": "ctrl+alt+o",
        "command": "workbench.action.files.openFolder",
        "when": "openFolderWorkspaceSupport"
    },
    {
        "key": "ctrl+k ctrl+o",
        "command": "-workbench.action.files.openFolder",
        "when": "openFolderWorkspaceSupport"
    }
]","linux":"// Place your key bindings in this file to override the defaults
[
    {
        "key": "ctrl+shift+b",
        "command": "-workbench.action.tasks.build",
        "when": "taskCommandsRegistered"
    },
    {
        "key": "ctrl+shift+alt+b",
        "command": "workbench.action.activityBarLocation.hide"
    },
    {
        "key": "shift+alt+b",
        "command": "workbench.action.activityBarLocation.default"
    }
]"}
